#ifndef PS2_VU1_NATIVE_H
#define PS2_VU1_NATIVE_H
// CL-0218: ahead-of-time compiled VU1 programs (generated by svr06-recomp/tools/vu1bench/gen.cpp into ps2_vu1_native_gen.cpp).
// A native program is the runFast loop body unrolled per instruction pair with the pair's decode as constants. All state stays in
// VU1Interpreter, so a native function may return at any pair boundary and the interpreter carries on from m_state.pc.
// Return value: 1 = program ended (E-bit), 0 = continue in the interpreter (limit reached, or next pair not compiled).
#include "runtime/ps2_vu1.h"
#include "ps2_vu1_inline.h"
#include <cstdint>
#include <cstring>

typedef int (*Vu1NativeFn)(VU1Interpreter &vu, uint8_t *vuData, uint32_t dataSize, GS &gs, PS2Memory *memory, uint64_t limit);
struct Vu1NativeProg
{
    uint32_t entryPc;        // byte PC of the entry
    uint32_t pairCount;      // number of compiled pairs
    const uint16_t *pairs;   // pair indices (pc / 8), ascending
    const uint32_t *words;   // lower, upper for each pair (the code this program was compiled from)
    Vu1NativeFn fn;
};
extern const Vu1NativeProg g_vu1NativeProgs[];
extern const uint32_t g_vu1NativeProgCount;
extern const Vu1NativeProg g_vu0NativeProgs[];   // CL-0371: VU0 micro programs (4 KiB code)
extern const uint32_t g_vu0NativeProgCount;

#define VN_HEAD(PC) s.pc = (PC); if (vu.m_cycle >= limit || vu.m_stopRequested) return 0;
#define VN_FDIV() if (vu.m_fdiv.valid && vu.m_fdiv.readyCycle > vu.m_cycle) vu.m_cycle = vu.m_fdiv.readyCycle;
#define VN_COMMIT() if (vu.m_cycle >= vu.m_minReady) { if ((vu.m_pendMask & ~1u) == 0u) vu.commitFlagsOnlyInl(); else vu.commitReadyPipelines(); }
#define VN_TAIL(NEXT) s.vf[0][0] = 0.0f; s.vf[0][1] = 0.0f; s.vf[0][2] = 0.0f; s.vf[0][3] = 1.0f; s.vi[0] = 0; s.pc = (NEXT);
#define VN_BRANCH() if (s.branchPending) { if (s.branchDelay == 0u) { s.pc = s.branchTarget & 0x3FFFu; s.branchPending = false; } else --s.branchDelay; }
#define VN_BRANCH0() if (s.branchPending) { if (s.branchDelay == 0u) { s.pc = s.branchTarget & 0xFFFu; s.branchPending = false; } else --s.branchDelay; }
// stage 2: nv[r] = cached norm4() of vf[r] (r = 32: ACC), valid when bit r of nvV is set; vf0 is constant at pair boundaries
#define VN_N(R) ((nvV & (1ull << (R))) ? nv[R] : (nvV |= (1ull << (R)), nv[R] = vu1inl::norm4((R) == 32 ? s.acc : s.vf[(R) & 31])))
#define VN_TAILQ(NEXT) s.pc = (NEXT);
#ifdef VN_CHECK
#define VN_CHK(PC) Vu1Native::chk(vu, nv, nvV, (PC));
#else
#define VN_CHK(PC)
#endif
#endif
